<script>
(function(){
 const input=document.getElementById('oysListSearch');const body=document.getElementById('oysTableRows');const noMatch=document.getElementById('oysNoMatch');if(!input||!body)return;
 input.addEventListener('input',function(){const q=this.value.trim().toLocaleLowerCase();let count=0;body.querySelectorAll('tr[data-search-row]').forEach(row=>{const match=row.textContent.toLocaleLowerCase().includes(q);row.style.display=match?'':'none';if(match)count++;});if(noMatch)noMatch.style.display=count===0&&q?'table-row':'none';});
})();
</script>
